class MagicScroll {
  constructor(powerLevel) {
    this.powerLevel = powerLevel;
  }

  cast() {
    throw new Error("The 'cast' method must be implemented by subclasses.");
  }
}

class FireScroll extends MagicScroll {
  constructor(powerLevel) {
    super(powerLevel);
  }

  cast() {
    return `Ignites a powerful flame with ${this.powerLevel} intensity.`;
  }
}

class ShieldScroll extends MagicScroll {
  constructor(powerLevel) {
    super(powerLevel);
  }

  cast() {
    return `Conjures a magical shield absorbing ${this.powerLevel} damage.`;
  }
}

const fireBolt = new FireScroll(75);
const forceShield = new ShieldScroll(100);

console.log(fireBolt.cast());
console.log(forceShield.cast());

